// ── n8n Code 節點：arXiv Atom XML → 結構化 items（含 LaTeX 清理）──
// 模式：Run Once for All Items ｜ 語言：JavaScript
// 上游：HTTP Request 節點（arXiv API，Response Format = Text）

// ── 1. 取出 arXiv 回應的原始 XML 字串（相容不同輸出欄位）──
const j = $input.first().json;
let xml = typeof j === 'string' ? j
  : (typeof j.data === 'string' ? j.data
  : (typeof j.body === 'string' ? j.body : JSON.stringify(j)));

// ── 2. 切出每一筆 <entry>（arXiv 的 Atom XML 每篇論文一個 entry）──
const raw = xml.split('<entry>').slice(1); // 第 0 段是 feed 標頭，丟掉

// ── 3. 抓 tag 內容 + 去標籤 + 解 HTML entity ──
function pick(block, tag) {
  const m = block.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>'));
  if (!m) return '';
  return m[1]
    .replace(/<[^>]+>/g, ' ')      // 去掉巢狀 tag（如作者標籤）
    .replace(/\s+/g, ' ')          // 多空白 → 單空白（XML 常跨行）
    .trim()
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'");
}

// ── 4. 清理 LaTeX 數學式（arXiv 摘要原始內容是 LaTeX 源碼）──
function cleanLatex(s) {
  if (!s) return '';
  return s
    // 常見 LaTeX 命令 → Unicode 符號
    .replace(/\\mid/g, '|')
    .replace(/\\times/g, '×')
    .replace(/\\cdot/g, '·')
    .replace(/\\leq|\\le/g, '≤')
    .replace(/\\geq|\\ge/g, '≥')
    .replace(/\\approx/g, '≈')
    .replace(/\\pm/g, '±')
    .replace(/\\rightarrow|\\to/g, '→')
    .replace(/\\ldots|\\dots/g, '…')
    .replace(/\\alpha/g, 'α').replace(/\\beta/g, 'β').replace(/\\gamma/g, 'γ')
    .replace(/\\delta/g, 'δ').replace(/\\theta/g, 'θ').replace(/\\lambda/g, 'λ')
    .replace(/\\mu/g, 'μ').replace(/\\sigma/g, 'σ').replace(/\\pi/g, 'π')
    // 排版指令 \mathrm{...} / \text{...} 等 → 只留內容
    .replace(/\\(?:mathrm|text|mathbf|mathit|mathbb|mathcal|operatorname)\{([^{}]*)\}/g, '$1')
    // 上標 ^{...} → ^x；下標 _{...} → _x
    .replace(/\^\{([^{}]*)\}/g, '^$1')
    .replace(/_\{([^{}]*)\}/g, '_$1')
    // 移除殘留：$ 符號、剩下的 \命令
    .replace(/\$/g, '')
    .replace(/\\[a-zA-Z]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// ── 5. 輸出 items：n8n 節點的回傳格式是 [{ json: {...} }, ...] ──
return raw.map(e => ({
  json: {
    title: cleanLatex(pick(e, 'title')),
    summary: cleanLatex(pick(e, 'summary')),
    link: pick(e, 'id'),
    published: pick(e, 'published'),
  }
}));

// ── 預篩選：只取前 N 篇送 LLM（成本控制）──
const N = 5;  // 先只取 5 篇測試
return $input.all().slice(0, N);

// ── 聚合：解析 LLM 輸出 → 按評分排序 → 組成 Telegram 訊息 ──
const llm = $input.all();              // LLM 逐篇輸出（順序 = 輸入順序）
const src = $('Pre-filter').all();     // 原始論文資料（取 title / link）

// ⚠️ 若你的預篩選節點名稱不是 "Pre-filter"，把上面字串改成你的節點名稱

const papers = llm.map((it, i) => {
  const text = it.json.text || '';
  const srcItem = (src[i] && src[i].json) || {};
  return {
    title: srcItem.title || '(未知標題)',
    link: srcItem.link || '',
    summary: (text.match(/重點[:：]\s*(.+)/) || [])[1] || '(無摘要)',
    score: parseInt((text.match(/評分[:：]\s*(\d)/) || [])[1] || '0', 10),
    tag: (text.match(/標籤[:：]\s*(.+)/) || [])[1] || '',
  };
});

// 按評分排序（高 → 低），只取 Top 3
papers.sort((a, b) => b.score - a.score);
const top = papers.filter(p => p.score >= 4).slice(0, 5);

const today = new Date().toLocaleDateString('zh-TW', {
  timeZone: 'Asia/Taipei', year: 'numeric', month: '2-digit', day: '2-digit'
});

const lines = top.map((p, i) =>
  (i + 1) + '. [' + p.score + '★] ' + p.title + '\n' + p.summary + '\n' + p.link
);

const message = '🤖 每日 AI 情報 · ' + today
  + '（精選 ' + top.length + ' / ' + papers.length + ' 篇）\n\n'
  + lines.join('\n\n');

return [{ json: { message: message, count: top.length, total: papers.length } }];
